architecture.h4_f:
msg = CBOR{v:1, makomi, eyano_na, etindamaki_na}
ct = AES-GCM-256-Encrypter (k, mbala moko te, msg, aad = id_ya_shambre)
POST /api/ba chambre/{id}/messages {texte chiffre: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, makomi, eyano_na?, id_ya_thread?, elobeli?, etindami_na}
ct = AES-GCM-256-Encrypt (fungola_ya_shambre, nonce, pt, aad = hex (id_ya_shambre))
nsinga = CBOR{
  v: 1, 2 .
  ciphertext: hex(ct), // bolai ya variable
  nonce: hex(12 B), .
  pseudo_ya_motindi: hex(16 B), .
  etindamaki_na: unix_ms
} .

cryptoWire.h5_f:
libanda = CBOR{
  node_ya_liziba: hex32, .
  mosaleli_ya_cible: int64, .
  texte_ciffre_ya kati: ba octets, .
  inner_nonce: ba octets, .
  etindamaki_na: unix_ms
} .
sig = Ed25519-Sign (liziba_priv, libanda)
POST /fédération/kopesa { enveloppe: libanda, sig: hex64 }

auth.h1_f:
POST /api/bondimi/komisa nkombo
  { kombo ya mosaleli, mot de passe, x25519_fungola_ya_mokolo, kombo_ya_elakiseli, telefone?, email?, avatar_emoji }

Eyano 201 Esalemi:
  { elembo_ya_kokɔta, elembo_ya_kozongisa sika, ID_ya_mosaleli, nkombo ya mosaleli, ... }

auth.h3_f:
charge utile ya accès_token:
  { sub: id_ya_mosaleli, jti: id_ya_appareil, typ: "accès", exp: sikoyo + 15min }
charge utile ya refresh_token:
  { sub: id_ya_mosaleli, jti: id_ya_appareil, typ: "kozongisa sika", exp: sikoyo + 30d }

HS256-signé na sekele ya 64 octets ya node uta na .env

auth.h4_f:
enregistrer_ebandeli (): défi = rand (32) .
                    options = { rp.id, mosaleli.id, pubKeyCredParams, mokakatano }
                    ba options ya kozongisa

enregistrer_finish (bolimbisi): .
  vérifier attestation contre TPM / Misisa ya Enclave ya sécurité CA .
  magazini { id_ya_bondimi, fungola_ya_mokolo, motángi: 0 }

auth.h7_f:
POST /api/bondimi/qr/ebanda
  → { nonce: hex ya 128 bits, ttl: 60 }
QR charge utile = { mbala moko, id_ya_mosaleli, mosaleli: "https://node.exemple" }

POST /api/bondimi/qr/vérifier { nonce }
  → aparɛyi ya sika oyo ekomisami; Ba JWT bazongaki.

rooms.h6_f:
pseudo_ya_motindi = HMAC-SHA256(mungwa_ya_lokuta_ya_shambre, id_ya_motindi)[:16] // 32 hex
ciphertext = AES-GCM-Chiffrer(fungola_ya_shambre, nonce, charge_utile_CBOR, aad = id_ya_shambre)

Cadre ya ventilateur: { type:"m", chambre, msg:{id, ct, nonce, pseudo_ya_motindi, atindaki_na} }

files.h2_f:
init POST /api/fisyé/resumable/init {nkombo ya fisyé, bonene, likanisi_ya_taille_ya_chunk}
            ← {id_ya_kotia, bonene_ya_chunk}
chunk PUT /api/fisyé/ekoki kozongisama/{id_ya_kotia}/chunk/{offset} <ct bytes>
            ← 204. Ezali na ntina te
kosilisa POST /api/fichiers/resumable/{id_ya_upload}/kosilisa {plain_blake3}
            ← 201 {id_fisyé, url}
TTL na oyo esilaki te: 24 h

presence.h1_f:
client: na touche ya liboso → tinda {type:"t", état:"banda"}
         etindi lisusu te pona 3 s soki état ebongwani te
         10 s sima ya kofina touche ya suka → tinda {type:"t", état:"arrêt"}
récepteur: auto-arrêt 10 s sima ya "kobanda" ya suka soki "arrêt" moko te ekomaki

calls.h1_f:
POST /api/mabenga/{id_ya_shambre}/banda {vidéo, audio} → id_ya_kobenga
WS emission {lolenge:"c", lolenge:"kobengisa", call_id}
WS emission {lolenge:"c", lolenge:"offre", sdp}
WS emission {lolenge:"c", lolenge:"eyano", sdp}
WS emission {lolenge:"c", lolenge:"candidat",glace} × N
POST /api/kobenga/{id_ya_kobenga}/suka

gossip.h3_f:
piblisite = {fungola ya pub, esika ya suka, piblisite_na}
sig = Ed25519-Sign (priv_ya_fungola ya kobimisa, CBOR (piblisite))
charge utile ya masolo: [..., {public, sig}, ...]

récepteur: vérifier sig contre ad.pubkey → magasin iff ok
ya kobakisa: PoW ya 2^18 zéro ya liboso na {pubkey, point final}

push.h4_f:
iOS NSE: didReceive(bosengi) { déchiffrer(bosengi.makambo.Info ya mosaleli) }
Android FCM: onMessageReceived(Message ya mosika) { déchiffrer(Message ya mosika.donnée) }
Web SW: self.addEventListener ('kotindika', e => ko déchiffrer (e.donnée))

bots.h1_f:
kosala: POST /api/bots {nkombo ya mosaleli, nkombo_ya_elakiseli, code}
          → {bot_id, elembo, fungola ya pub}
kosala: na kati ya mosala (coroutine na kati ya node) .
      OR ya libanda (sondage ya molayi /api/bots/{id}/mabongisi, token-auth'd)
nsango: {mokanda, sinyatili: Ed25519-Sinyatili (bot_priv, canonical_msg)}

bots.h2_f:
na /kobanda { .
  emit "Boyei malamu, {ctx.kombo_ya_ya liboso}".
} .
na /bakisa <eloko> {
  état.liste = (état.liste to []) + [ctx.args.item].
  emit "Ebakisami: {ctx.args.item}"
} .

security.h4_f:
canary.txt (mokolo na mokolo):
  {mokolo, sig: Ed25519-Sign (priv_ya_bobimisi, mokolo)}
client azali ko vérifier → absent to invalide ⇒ compromis suspect

likambo ya mbalakaka:
  admin POST /api/admin/kolongola-nyonso {ntina}
  ba émissions ya node {type:"n", événement:"comprome", raison}
  ba clients ba effacer ba clés, ba forcer re-bootstrap

debugging.h2_f:
ba histogrammes ya taux (na nzela + méthode):
  vortex_http_requests_total{nzela,lolenge,ezalela}
  vortex_http_bosengi_bolai_segɔnde_seau{nzela,lolenge,le}

ba jauge ya websocket:
  vortex_ws_connexions{node}.
  vortex_ws_fanout_molongo_bozindo{sambre,mosaleli}

ba compteurs personnalisés:
  vortex_messages_esent_total{lolenge_ya_shambre}
  vortex_calls_ebandi_total{lolenge}.

login.h3_f:
{
  "nkombo ya mosaleli": "alice",
  "mot de passe": "agrafe ya pile ya mpunda oyo ebongi",
  "totp": "123456" // esengeli soki 2FA efungolami
} .

login.h4_f:
na succès: 201 + JWT enveloppe (forme moko na registre)
na 2FA esengeli: 200 { "esengeli_2fa": solo } (naino JWT te)
na échec: 401 { "libunga":"ba credentiels_invalides" }

apns.h1_f:
POST https://api.push.apple.com/3/eloko/<elembo_ya_esaleli>
Mitó ya makambo: apns-sujet: <id_bundle>, apns-push-type: alerte, apns-collapse-id: chambre:42
Nzoto: {aps: {alerte: {titre, nzoto}}, ba données: <ekangamaki>}

bmp.h1_f:
id_ya_boîte de poste = HKDF(fungola_ya_moyambi, info="bmp-v1", len=32)
Botiami: POST /bmp/botiami {id_boîte postale, blob ≤1MB}
Kozwa: GET /bmp/ba messages (auth'd)

controller.h1_f:
GET /v1/integrity → {état, signé_na, ekokani, ekokani te, ...}
GET /v1/santé → {ezalela, version, pubkey, statistiques}
GET /v1/ba entrées → [{protocole, url}, ...] Ezali na ntina mingi.
GET /v1/batalatala → [url_ya_mokonzi, ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/misala/<projet>/ba messages:tinda
Ndingisa: Mokumbi <oauth2_token>
Nzoto: {message: {jeton: <appareil>, ba données: {...ekangamaki...}, android: {clé_collapse}}}

federation.h1_f:
enveloppe = {node_ya_liziba, mosaleli_ya_cible, ct_ya_kati, nonce_ya_kati, etindamaki_na}
sig = Ed25519-Sign (liziba_priv, CBOR (envɛlɔpi))
POST /fédération/kopesa {enveloppe, sig}
B e vérifier: sig contre ba fédérations[source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE ba messages_fts USING makolo5(
  contenus, -- colonne oyo esalemi na bilembo
  id_ya_shambre UNINDEXED, .
  tokenize = 'unicode61 kolongola_diacritique 2'.
);
motuna: SELECT rowid FROM ba messages_fts WHERE makambo MATCH 'foo'.

gravitix.h1_f:
on /start { emit "Boyei malamu, {ctx.kombo_ya_ya liboso}" }
na /bakisa <eloko> {
  état.liste = (état.liste to []) + [ctx.args.item].
  emit "Ebakisami: {ctx.args.item}"
} .

vapid.h1_f:
VAPID ba touches: Ed25519 ba touches na noeud moko
elembo JWT: {aud: push_service_origine, exp: sikoyo + 12h, sub: mailto:ops@ndakisa}
mitó ya bosengi ya kopusa: Ndingisa: vapid t=<jwt>, k=<vapid_fungola_ya bato banso>
